221	    /**
222	     * Rejects creating an owner whose city already contains {@value #CITY_CAPACITY} or more owners.
223	     * Owners are counted per city comparing the city name case-insensitively (a {@code null} city is
224	     * treated as empty), the same way {@link #assignCustomerCode} counts a city's owners.
225	     *
226	     * @param city the city of the owner being created
227	     * @throws CityAtCapacityException (409 Conflict) if the city is already at capacity
228	     */
229	    private void rejectCityAtCapacity(String city) {
230	        String cityValue = city == null ? "" : city;
231	        long count = this.clinicService.findAllOwners().stream()
232	            .filter(existing -> cityValue.equalsIgnoreCase(
233	                existing.getCity() == null ? "" : existing.getCity()))
234	            .count();
235	        if (count >= CITY_CAPACITY) {
236	            throw new CityAtCapacityException(city);
237	        }
