240	    /**
241	     * Assigns an owner's {@code customerCode} on create, formatted {@code '<CITY3>-<LAST3>-<NNNN>'}
242	     * where CITY3 is the upper-cased first three letters of the city, LAST3 the upper-cased first
243	     * three letters of the last name and NNNN a per-city 4-digit zero-padded sequence equal to one
244	     * more than the number of owners already in that city (e.g. {@code 'SYD-SMI-0007'}).
245	     *
246	     * @param city the owner's city
247	     * @param lastName the owner's last name
248	     * @return the assigned customer code
249	     */
250	    private String assignCustomerCode(String city, String lastName) {
251	        String city3 = prefix3(city);
252	        String last3 = prefix3(lastName);
253	        String cityValue = city == null ? "" : city;
254	        int sequence = (int) this.clinicService.findAllOwners().stream()
255	            .filter(existing -> cityValue.equalsIgnoreCase(
256	                existing.getCity() == null ? "" : existing.getCity()))
257	            .count() + 1;
258	        return String.format("%s-%s-%04d", city3, last3, sequence);
259	    }
