548	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
549	    @Override
550	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
551	        Owner owner = this.clinicService.findOwnerById(ownerId);
552	        if (owner == null) {
553	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
554	        }
555	        HttpHeaders headers = new HttpHeaders();
556	        Pet pet = petMapper.toPet(petFieldsDto);
557	        owner.setId(ownerId);
558	        pet.setOwner(owner);
559	        pet.getType().setName(null);
560	        this.clinicService.savePet(pet);
561	        PetDto petDto = petMapper.toPetDto(pet);
562	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
563	            .buildAndExpand(pet.getId()).toUri());
564	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
565	    }
566	
567	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
568	    @Override
569	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
570	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
571	        if (currentOwner != null) {
572	            Pet currentPet = this.clinicService.findPetById(petId);
573	            if (currentPet != null) {
574	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
575	                currentPet.setName(petFieldsDto.getName());
576	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
577	                this.clinicService.savePet(currentPet);
578	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
579	            }
580	        }
581	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
582	    }
583	
584	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
585	    @Override
586	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
587	        HttpHeaders headers = new HttpHeaders();
588	        Visit visit = visitMapper.toVisit(visitFieldsDto);
589	        Pet pet = new Pet();
590	        pet.setId(petId);
591	        visit.setPet(pet);
592	        this.clinicService.saveVisit(visit);
593	        VisitDto visitDto = visitMapper.toVisitDto(visit);
594	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
595	            .buildAndExpand(visit.getId()).toUri());
596	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
597	    }
598	
599	
600	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
601	    @Override
602	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
603	        Owner owner = this.clinicService.findOwnerById(ownerId);
604	        if (owner != null) {
605	            Pet pet = owner.getPet(petId);
606	            if (pet != null) {
